
from pathlib import Path
import argparse

import joblib
import pandas as pd


def predict_updates(input_path, output_path):
    model_path = Path(__file__).resolve().parent / "poisoning_detector.joblib"

    # Load the trained Random Forest and its feature names.
    saved_data = joblib.load(model_path)
    classifier = saved_data["model"]
    feature_columns = saved_data["features"]

    # Read model updates generated by C#.
    updates = pd.read_csv(input_path)

    # Select exactly the features used during training.
    features = updates[feature_columns]

    # Predict whether each update is malicious.
    predictions = classifier.predict(features)
    probabilities = classifier.predict_proba(features)[:, 1]

    # Preserve the update identifiers for the C# application.
    results = updates[["SimulationId", "UavId", "Round"]].copy()

    results["PredictedMalicious"] = predictions
    results["MaliciousProbability"] = probabilities

    # Write results for C# to read.
    output_path.parent.mkdir(parents=True, exist_ok=True)
    results.to_csv(output_path, index=False)

    print(f"Updates classified: {len(results)}")
    print(f"Suspicious updates: {sum(predictions)}")
    print(f"Predictions saved to: {output_path}")


def main():
    parser = argparse.ArgumentParser(
        description="Classify federated learning model updates."
    )

    parser.add_argument("input_csv", type=Path)
    parser.add_argument("output_csv", type=Path)

    args = parser.parse_args()

    predict_updates(args.input_csv, args.output_csv)


if __name__ == "__main__":
    main()
